import sys, json, os; sys.path.insert(0, '.')
from docx_helpers import *
import packdata as PD
MK = json.load(open('market.json')); MF = {f['id']: f for f in MK['facts']}
BAL = 'The balance of project funding is provided by Jalour sponsor equity, project collections and other capital sources.'
def build_dd(k, T, path):
    D = PD.build(k, T); I = D['info']; A = D['A']; B = D['B']; F = D['fund']; S1 = B['S']['S1']['res']; S2 = B['S']['S2']['res']; S3 = B['S']['S3']['res']
    NAME = I['name']; pm = B['pay_months']; inst = B['mult']*T/12; t0 = 3 if k == 'GS' else 12
    pr = D['prices']; pl_c, pl_a = pr['launch']; pf_c, pf_a = pr['final']; ap_c, ap_a = pr['avg']; sp = D['sens']; j = A['jal']
    def one(toc=None):
        d = Doc(f'{NAME} - Due Diligence Memorandum (EGP {T} million)', f'Jalour Developments  |  {NAME} Due Diligence Memorandum  |  Strictly private and confidential'); dd = d.d
        for _ in range(5): dd.add_paragraph()
        d.p('STRICTLY PRIVATE AND CONFIDENTIAL', bold=True, size=10, color=BRASS)
        d.p(NAME, bold=True, size=34, color=NAVY, after=2); d.p('Due Diligence Memorandum', bold=True, size=18, color=NAVY, after=6)
        d.p(f'Private placement of EGP {T} million. Companion to the Investment Memorandum and Financial Annex.', size=12, after=30)
        d.p('Issued by Jalour Developments, a subsidiary of Al Jalal Holding, Cairo. October 2026.', size=10.5, color=GREY)
        d.h1('Purpose and status')
        d.p('This memorandum helps the investor and its advisers plan and carry out due diligence. It lists the documents Jalour will provide, the legal and regulatory structure, the evidence behind the main assumptions, the opinions and security documents required, a candid list of red flags, and the open items. It describes status as at October 2026. Items marked [After NDA] are provided after the investor signs a non-disclosure agreement; items marked [Pending] are being prepared. It is not legal advice.')
        d.p('Where this memorandum and the Investment Memorandum differ, the Investment Memorandum and the Financial Annex are the reference for figures; the definitive agreements prevail over both.')
        d.h1('Contents')
        items = ['1. Corporate and project-company structure', '2. Al Ahly Sabbour agreement and consent status', '3. Permits, licences and land status', '4. Construction and cost basis', '5. Sales and pricing evidence', '6. Legal and regulatory structure, and opinions required', '7. Security documentation', '8. Structures considered and rejected', '9. Risks and mitigants', '10. Red-flag disclosure list', '11. Questions an investor is likely to ask', '12. Data-room index', '13. Open items']
        for t in items:
            par = dd.add_paragraph(); par.paragraph_format.space_after = Pt(3); par.paragraph_format.tab_stops.add_tab_stop(Cm(16.3), alignment=2, leader=1)
            r = par.add_run(t + '\t' + (str(toc.get(t, '')) if toc else '')); r.font.size = Pt(11)
        # 1
        d.h1('1. Corporate and project-company structure')
        d.table([['Layer', 'Entity', 'Status'], ['Holding', 'Al Jalal Holding, Cairo', '[After NDA]'], ['Sponsor and developer', 'Jalour Developments', '[After NDA]'], ['Project company', '[Name, jurisdiction and capital to be confirmed]', 'To be formed or confirmed; holds the project rights and issues the investor entitlement'], ['Landowner', 'Al Ahly Sabbour', 'Counterparty under the development agreement'], ['Investor', '[Name]', 'KYC and source-of-funds to be completed']], [3.6, 5.8, 6.9], 'Structure', -1, font=9.5, bold_first_col=True)
        d.bullets(['The project is held in its own company. There is no cross-collateral and no cross-default with other Jalour projects. The investor has no exposure to other Jalour projects.', 'The legal form of the investor\'s entitlement (equity, loan or contractual entitlement) is open and drives tax, regulation and enforceability. Counsel to advise; see section 6.', 'No funds are ring-fenced or held in restricted accounts under the proposed structure. Jalour\'s position is that the rule requiring a separate project account for developers on state-allocated land does not apply to these plots; the basis is in the data room.', BAL])
        d.p('Jalour may raise further capital at project or holding level, subject to the investor\'s stated rights as to ranking, collateral and information. This is a standard term and does not offer exclusivity.')
        # 2
        d.h1('2. Al Ahly Sabbour agreement and consent status')
        d.table([['Term (from the Jalour model)', 'Detail', 'Evidence to provide'], ['Landlord share', '35% of collections', 'Signed agreement'], ['Minimum guarantee', f'EGP {fmt(I["guarantee"],0)} million over six years', 'Schedule and payment mechanics'], ['Down payment', f'EGP {fmt(I["dp"],0)} million (10%)', 'Proof of payment or payment date'], ['Guarantee schedule', ', '.join(f'Y{n+1} {fmt(x,0)}' for n, x in enumerate(I['sched'])) + ' (EGP million)', 'Agreement schedule'], ['Excess over guarantee', f'Settled from year {I["excess_years"]}', 'Settlement clause'], ['Scope', 'Jalour designs, permits, builds (core and shell), markets, sells, collects, operates', 'Scope and approvals clauses'], ['Delivery', f'Project month {I["delivery"]}', 'Delivery covenant, remedies for delay']], [4.4, 6.4, 5.5], 'Agreement terms and evidence', -1, font=9.5, bold_first_col=True)
        d.h2('Consent requirements and status')
        d.table([['Consent', 'Needed for', 'Status'], ['Allocation of units to the investor', 'Option A', '[Status after NDA]'], ['Assignment of the investor\'s contract before handover', 'Option A', '[Status after NDA]'], ['Earmark of unsold units as collateral', 'Option B', '[Status after NDA]'], ['Acknowledgement that landlord payments are unchanged and borne by Jalour', 'Both', '[Status after NDA]'], ['Any assignment of collections or encumbrance affecting the landlord share', 'Not proposed', 'Not required unless the structure changes']], [8.0, 3.2, 5.1], 'Consents', -1, font=9.5)
        d.p('Receipt of the landlord\'s written consent is a condition precedent to signing. The investor should see the consent before funding.')
        # 3
        d.h1('3. Permits, licences and land status')
        d.table([['Item', 'Status', 'Document'], ['Land title and allocation to the landowner', '[After NDA]', 'Title deed, allocation contract, master-developer approvals'], ['Master-plan and detailed-plan approval for the plot', '[After NDA]', 'Ministerial or authority approval'], ['Building permit and licences', '[After NDA]', 'Permit, civil defence, utilities'], ['Environmental and utilities approvals', '[After NDA]', 'Approvals and capacity letters'], ['Sales approval before launch', '[After NDA]', 'Authority approval to announce and sell (see section 6)'], ['Design and consultant appointment', '[After NDA]', 'Appointment letters, design approvals']], [6.3, 3.0, 7.0], 'Permit and land status', -1, font=9.5)
        d.p('Prime Minister Decree 2184 of 2022 reportedly bars developers on state-allocated land from announcing sales before approval of the general and detailed plans (Invest-Gate; Mondaq). Jalour\'s position is that it does not apply to these plots; the basis is provided in the data room after the investor signs a non-disclosure agreement.')
        # 4
        d.h1('4. Construction and cost basis')
        d.table([['Cost line', 'EGP million', 'Basis'], ['Construction (core and shell)', fmt(D['base']['cons'], 1), 'Stage schedule scaled by a factor of 8 in the model [Jalour to explain what the factor represents and provide contractor pricing]'], ['Sales commission', fmt(D['base']['commission'], 1), '4% of sales value, paid 12 months after each sale quarter'], ['SG&A and others', fmt(D['base']['sga'], 1), '15% of construction: contingency 5%, professional fees 5%, overhead 5%']], [5.2, 2.5, 8.6], 'Cost basis', 1, font=9.5)
        d.table([['Stage group (model unit schedule)', 'EGP million before factor of 8'], ['Excavation and replacement', '5.800'], ['Concrete structure', '14.900'], ['Building works', '1.320'], ['MEP and plumbing', '40.000'], ['Curtain walls', '21.000'], ['Landscape', '4.125'], ['Total per unit schedule', '87.145']], [10.0, 6.3], 'Stage cost schedule in the model', 1, font=9.5, total_row=True)
        d.bullets([f'Cost per m2 of built-up area is about EGP {fmt(D["base"]["cons"]*1e6/I["bua"]/1000,1)} thousand, for core and shell including a basement stage. Jalour to provide a bill of quantities and contractor quotation to support it.', 'The model applies no construction cost inflation over the 36-month build. Jalour\'s working papers contain a construction-cost index that is not applied in the model. A 10% overrun reduces project NPV by EGP ' + fmt(D['base']['npv']-sp['cost'][1.1]['npv'], 0) + ' million and a 20% overrun by EGP ' + fmt(D['base']['npv']-sp['cost'][1.2]['npv'], 0) + ' million.', 'Design, permit and pre-construction costs are not separately modelled. The funding plan adds EGP ' + fmt(F['uses']['precon'], 1) + ' million as an assumption.', 'Independent engineer review of cost and programme is recommended (optional protection).'])
        # 5
        d.h1('5. Sales and pricing evidence')
        d.table([['EGP per m2', 'Plan: launch', 'Plan: delivery list', 'Plan: average realised', 'Market evidence (asking)'], ['Offices', fmt(pl_a*1000, 0), fmt(pf_a*1000, 0), fmt(ap_a*1000, 0), '106,000 to 120,000 (Mostakbal City listings, 2026)'], ['Retail', fmt(pl_c*1000, 0), fmt(pf_c*1000, 0), fmt(ap_c*1000, 0), '139,000 to 325,000 (New Cairo listings, individual)']], [2.2, 2.6, 2.6, 3.2, 5.7], 'Pricing against market evidence', 1, font=9)
        d.bullets([f'The plan raises list prices by {(pf_c/pl_c-1)*100:.0f}% (retail) and {(pf_a/pl_a-1)*100:.0f}% (offices) from the first to the last sales tranche. New Cairo secondary prices rose 3.1% y/y in Q1 2026 (JLL via Enterprise); broker estimates for 2026 are 10% to 16% a year (a blog estimate). Against today\'s office asking prices (mid-point EGP 113,000) the delivery list is +{D["pricecmp"]["off_vs_ask"]*100:.0f}%, about {D["pricecmp"]["off_cagr"]*100:.0f}% a year to handover.', f'Sellable office area in the model is {fmt(I["admin_sales_area"],0)} m2, against {fmt(I["office"],0)} m2 of office built-up area. Jalour to provide the sellable-area schedule. If the lower area were right, office sales at 80% would be about EGP {fmt(sum(t["admin"] for t in D["tranches"])*(1-I["office"]/I["admin_sales_area"]),0)} million lower.', 'Payment plans: down payment 5% to 20%, equal second payment after three months, instalments over 2 to 8 years, delivery payment 20% to 25%. Delivery payments are collected on a contractual milestone before handover; Jalour to provide the standard sale contract showing the milestone.', 'No sales have been contracted yet [Jalour to confirm]. Evidence to provide: broker valuation, comparable transactions, reservation register once sales begin.'])
        d.table([['Sales sensitivity', 'NPV (EGP m)', 'Peak shortage (EGP m)']] + [[f'Prices {int((f-1)*100):+d}%', fmt(sp['price'][f]['npv'], 0), fmt(-sp['price'][f]['peak'], 0)] for f in (0.8, 0.9, 1.1)] + [[f'Sales delayed {q*3} months', fmt(sp['delay'][q]['npv'], 0), fmt(-sp['delay'][q]['peak'], 0)] for q in (2, 4, 8)] + [['Delivery payments at handover', fmt(D['proj']['Delivery payments at handover']['npv'], 0), fmt(-D['proj']['Delivery payments at handover']['peak'], 0)]], [7.8, 4.2, 4.3], 'Sales sensitivities (Jalour net cash flow)', 1, font=9.5)
        # 6
        d.h1('6. Legal and regulatory structure, and opinions required')
        d.h2('6.1 Questions for counsel (no legal conclusions are given here)')
        d.bullets(['Nature of the instrument and whether the placement needs any filing, approval or exemption with the Financial Regulatory Authority or another body; investor eligibility.', 'The basis for Jalour\'s position that the separate project-account rule for developers on state-allocated land (Decree 2184 of 2022) does not apply to these plots. The proposed structure does not ring-fence funds.', 'Validity, assignability and any change-of-control or consent clauses in the landlord agreement.', 'Enforceability of the unit allocation, the earmark and negative pledge, and of any promissory notes or post-dated cheques.', 'Rules on assignment (resale) of off-plan contracts and on developer consent and fees.', 'Foreign investor matters: ownership of units, repatriation of proceeds and foreign-exchange availability.', 'Tax: withholding on Option B payments, tax on Option A resale gains, registration fees and real estate disposal tax.'])
        d.h2('6.2 Opinions and certificates required')
        d.table([['Opinion or document', 'Given by', 'Status'], ['Capacity, authority and due execution (project company, Jalour)', 'Jalour counsel', '[Pending]'], ['Enforceability of the investment agreement and security', 'Jalour counsel', '[Pending]'], ['Title and rights to the plot; landlord agreement validity', 'Counsel', '[Pending]'], ['Regulatory position of the placement', 'Counsel', '[Pending]'], ['Tax opinion on both options', 'Tax adviser', '[Pending]'], ['Foreign investor and repatriation opinion (if applicable)', 'Counsel', '[Pending]']], [8.5, 3.6, 4.2], 'Opinions', -1, font=9.5)
        # 7
        d.h1('7. Security documentation')
        d.table([['Document', 'Parties', 'Applies to'], ['Investment agreement', 'Project company, Jalour, investor', 'Both options'], ['Unit allocation agreements (registered)', 'Project company, investor', 'Option A'], ['Landlord consent and acknowledgement', 'Al Ahly Sabbour, project company, investor', 'Both'], ['Earmark and negative pledge over unsold units', 'Project company, investor', 'Option B'], ['Payment priority and information undertaking', 'Project company, Jalour, investor', 'Option B'], ['Sponsor funding undertaking (project funding gaps; not a return guarantee)', 'Jalour, project company', 'Both'], ['Promissory notes or post-dated cheques (optional)', 'Project company, investor', 'Option B'], ['Corporate approvals, incumbency, KYC', 'All', 'Both']], [7.4, 6.0, 2.9], 'Documents', -1, font=9.5)
        d.p('Nothing in the package is a restricted account, escrow or segregated collection account. The investor\'s protection rests on covenants, reporting and the earmarked or allocated units, and on Jalour\'s funding undertaking.')
        # 8
        d.h1('8. Structures considered and rejected')
        d.h2('8.1 Option A: source of units')
        d.p('The units must come from sellable inventory that carries the launch list price. Jalour has decided not to use the 20% of units it retains.')
        d.table([['Source considered', 'Jalour cost of capital', 'NPV to Jalour at 14% (EGP m)', 'Effect'], [f'First two sales tranches at launch list (recommended)', pct(j['irr']), fmt(j['npv'], 1), 'Removes ' + pct(A['f'], 0) + ' of those tranches; landlord payments unchanged'], ['Same area taken pro rata from all tranches (higher average prices)', pct(j['prorata_irr']), fmt(j['prorata_npv'], 1), 'Costs more because later units are priced higher'], ['Retained 20% of units', 'Not considered', 'n/a', 'Excluded by Jalour']], [6.2, 3.0, 3.6, 3.5], 'Unit sources', 1, font=9.5)
        d.p(f'A mix of retail and offices in proportion to the launch tranches (retail {pct(A["retail_share"],0)}, offices {pct(1-A["retail_share"],0)}) is recommended. Retail alone would exceed the retail inventory of those tranches at larger tickets. Offices alone are possible but are the harder asset to replace in the early sales.')
        d.h2('8.2 Option B: payout structures')
        d.table([['Structure', 'Investor IRR (base)', 'Quarters < 1.5x (net cash flow)', 'Downside lowest pooled cash (EGP m)', 'Why rejected or chosen'], ['S1 fixed multiple, equal instalments', pct(S1['Base']['irr']), f'{S1["Base"]["strict_below"]} of {S1["Base"]["n"]}', fmt(S1['Downside']['min_cash'], 0), 'Chosen: simple and certain'], [f'S2 {pct(B["params"]["S2_pct"],1)} of collections, floor and cap', pct(S2['Base']['irr']), f'{S2["Base"]["strict_below"]} of {S2["Base"]["n"]}', fmt(S2['Downside']['min_cash'], 0), 'Takes cash needed for construction; no better coverage'], [f'S3 fixed 1.8x plus {pct(B["params"]["S3_pct"],1)} of collections', pct(S3['Base']['irr']), f'{S3["Base"]["strict_below"]} of {S3["Base"]["n"]}', fmt(S3['Downside']['min_cash'], 0), 'More complex; same coverage issue']], [4.7, 2.2, 2.7, 3.0, 3.7], 'Option B structures', 1, font=9)
        d.p('A 1.5x coverage test on quarterly net cash flow cannot be met in the construction-peak quarters by any structure that pays in them. Reducing the multiple would not cure it. The structure therefore pays on a fixed schedule, discloses the shortfall, and relies on pooled cash, the payment priority covenant and Jalour\'s funding undertaking.')
        # 9
        d.h1('9. Risks and mitigants')
        d.table([['Risk', 'Effect on the investor', 'Mitigant', 'Residual'], ['Price below plan', 'Option A value falls; project cash weaker', 'Downside case; Option B unaffected by price', 'Medium'], ['Sales delay', 'Funding peak EGP ' + fmt(-sp['delay'][4]['peak'], 0) + ' million at 12 months', 'Jalour funding; phased sales', 'High'], ['Delivery payments at handover', 'Peak EGP ' + fmt(F['stress_peak'], 0) + ' million', 'Contractual milestone; Jalour funding', 'Medium'], ['Cost overrun', 'NPV down EGP ' + fmt(D['base']['npv']-sp['cost'][1.1]['npv'], 0) + ' million per 10%', 'Contingency; fixed-price contracts; engineer', 'Medium'], ['Landlord consent or dispute', 'Allocation blocked or delayed', 'Condition precedent', 'Low if obtained'], ['Jalour funding capacity', 'Option B payouts depend on it in downside', 'Funding undertaking; audited accounts; payment priority', 'High'], ['Legal and regulatory', 'Structure may need change', 'Counsel review before signing', 'Medium'], ['Liquidity', 'No market for Option B; Option A resale discount', 'Contractual schedule; early-assignment table', 'Medium']], [3.7, 4.6, 5.4, 2.6], 'Risk register', -1, font=9)
        # 10
        d.h1('10. Red-flag disclosure list')
        d.p('Candid disclosure protects both sides. These points are known to Jalour and may reduce the investor\'s return or increase risk.', keep=True)
        d.numbered([f'**Delivery payments are collected before handover.** The model collects them at project month {30 if k == "GS" else 45}, {I["delivery"]-(30 if k == "GS" else 45)} months before handover. If collected at handover the peak shortage is EGP {fmt(F["stress_peak"],0)} million, not EGP {fmt(F["model_peak"],1)} million.',
                    f'**Price growth.** The plan needs list prices to rise {(pf_c/pl_c-1)*100:.0f}% (retail) and {(pf_a/pl_a-1)*100:.0f}% (offices); launch office prices exceed current Mostakbal City asking prices; recent growth evidence is mixed.', f'**Sellable office area** ({fmt(I["admin_sales_area"],0)} m2) exceeds office built-up area ({fmt(I["office"],0)} m2); not yet reconciled.',
                    '**Cost basis.** Construction cost is a stage schedule multiplied by a factor of 8 that is not yet explained; no inflation; no separate pre-construction cost.', '**No sales are contracted yet** and the permit, title and consent documents in sections 2 and 3 are provided after the investor signs a non-disclosure agreement.',
                    f'**Payout coverage.** Net cash flow covers Option B instalments by 1.5x or more in only {S1["Base"]["n"]-S1["Base"]["strict_below"]} of {S1["Base"]["n"]} quarters; the minimum on net cash flow is {mx(S1["Base"]["strict_min"],1)}. Pooled cash covers at least {mx(S1["Base"]["liq_min"],1)} in the base case.',
                    f'**Downside funding need.** With sales delayed 12 months and prices 10% lower the funding need is EGP {fmt(F["downside_peak"],0)} million and the lowest pooled cash after Option B payouts is EGP {fmt(S1["Downside"]["min_cash"],0)} million. The investor relies on Jalour\'s capacity to fund it; there is no parent guarantee and no restricted account.',
                    f'**Option A uses the first sales tranches.** The investor receives {pct(A["f"],0)} of the launch-priced inventory, which raises the peak shortage before the ticket from EGP {fmt(F["model_peak"],1)} million to EGP {fmt(-j["peak_ex_ticket"],1)} million and gives the investor units that compete with Jalour\'s later sales.', '**Commission timing.** The model pays commission 12 months after each sale quarter; if paid at sale, early funding needs are higher.',
                    '**Sponsor information** (track record, audited accounts) is provided only after the investor signs a non-disclosure agreement, and the **form of the investor\'s instrument** is still open.', '**Market data** are reported from third-party summaries and asking prices; they are not audited.'])
        if 'combined' in D:
            C = D['combined']; d.p(f'**Sponsor capacity (additional).** Jalour\'s funding undertaking draws on its cash reserves and on other projects\' cash. The combined view of {NAME} and {C["other"]["name"]} (Investment Memorandum, section 11.2) shows a base-case combined low of EGP {fmt(-C["comb_min"],1)} million in month {C["comb_min_m"]}, but in the downside case both projects are short at the same time and the combined peak shortage is EGP {fmt(-C["scen"]["Downside: sales +12 months, prices -10%"]["comb_peak"],0)} million.')
        # 11
        d.h1('11. Questions an investor is likely to ask')
        qa = [('Is the price growth realistic?', f'The plan needs +{(pf_c/pl_c-1)*100:.0f}% retail and +{(pf_a/pl_a-1)*100:.0f}% offices. Evidence is mixed (section 5). Option B removes the exposure; the Option A downside shows {pct(A["inv"]["Downside"]["irr"])} IRR.'),
              ('What if delivery payments are not received early?', f'Peak funding rises to EGP {fmt(F["stress_peak"],0)} million (Investment Memorandum, section 11). Jalour funds the gap.'),
              ('Who pays if the project has a gap?', 'Jalour has said it will cover project funding gaps from its cash reserves and from cash generated by other projects it is constructing. The form and cap are to be documented; see red flag 7.'),
              ('Why is coverage below 1.5x in some quarters?', 'Instalments fall in the construction peak. The disclosure is in Investment Memorandum section 13.3.'),
              ('Can I sell the units early?', 'Only the contract, with Jalour consent and landlord acknowledgement, and likely at a discount (Investment Memorandum section 16).')]
        for q, a in qa: d.p(f'**{q}** {a}')
        # 12
        d.h1('12. Data-room index')
        d.table([['No.', 'Folder', 'Contents', 'Status'], ['1', 'Corporate', 'Constitutional documents, registrations, board approvals, structure chart', '[After NDA]'], ['2', 'Landlord', 'Agreement with Al Ahly Sabbour, payment schedule, down payment proof, consents', '[After NDA]'], ['3', 'Land and permits', 'Title, plans approvals, building permit, licences', '[After NDA]'], ['4', 'Design and cost', 'Drawings, area schedule, bill of quantities, contractor quotes, programme', '[After NDA]'],
                 ['5', 'Sales', 'Price list, payment plans, standard sale contract, valuation, comparables', '[After NDA]'], ['6', 'Financial model', 'Financial Annex (provided with this pack)', 'Provided'], ['7', 'Sponsor', 'Track record, team, audited accounts of Jalour and Al Jalal Holding', '[After NDA]'], ['8', 'Legal', 'Draft investment agreement, security documents, opinions', '[After NDA]'], ['9', 'Market', 'Reports and sources cited in Investment Memorandum Appendix D', 'Provided (citations)']], [1.1, 3.2, 9.0, 3.0], 'Data-room index', -1, font=9.5)
        # 13
        d.h1('13. Open items')
        d.table([['No.', 'Item', 'Owner'], ['1', 'Landlord written consent: allocation, assignment, earmark', 'Jalour'], ['2', 'Legal form of the investor\'s instrument, project company name and jurisdiction', 'Jalour and counsel'], ['3', 'Confirm Jalour will not guarantee the return; documentation of the funding undertaking (form, amount)', 'Jalour'], ['4', 'Evidence that delivery payments are contractual before handover', 'Jalour'], ['5', 'Area schedule reconciling sellable and built-up office area', 'Jalour'], ['6', 'Cost basis: contractor quote, bill of quantities, factor of 8, pre-construction budget', 'Jalour'], ['7', 'Permits, licences, title status', 'Jalour'], ['8', 'Track record, team, audited financial statements', 'Jalour'], ['9', 'Regulatory position of the placement; separate project account question', 'Counsel'], ['10', 'Secondary transfer rules and fees for unit contracts', 'Jalour and counsel'], ['11', 'Foreign investor, FX and repatriation treatment', 'Counsel'], ['12', 'Verification of market data against original sources', 'Jalour']], [1.2, 11.7, 3.4], 'Open items', -1, font=9.5)
        d.save(path); return d
    d1 = one(); d1.save(path)
    pdf, pages = pdf_pages(path); toc = find_pages(d1.headings, pages)
    d2 = one(toc); d2.save(path); pdf, pages = pdf_pages(path)
    return dict(pages=len(pages), pdf=pdf)
if __name__ == '__main__':
    print(build_dd(sys.argv[1], int(sys.argv[2]), sys.argv[3]))
